import base64
import json
import logging
import re
from typing import Dict

from processing.models.data.preprocessing.member import MemberImageData
from processing.models.tags import MemberTag, MemberType

default_avatar = b''


class MemberProcessingTransformerSenat:

    @staticmethod
    def extract_name_fields(tag: MemberTag, data: Dict):
        names = data['name'].split(' ')

        if len(names) > 3:
            logging.warning(f"Member name: {data['name']} has more than 3 parts")
        elif len(names) == 0:
            raise ValueError(f"Member has 0 parts - {data}")

        return {
            **data,
            "firstName": names[0],
            "lastName": names[-1],
            "secondName": names[1] if len(names) > 2 else "",
        }

    @staticmethod
    def add_member_voting_name_field(tag: MemberTag, data: Dict):
        return {
            **data,
            "votingName": data["name"]
        }

    @staticmethod
    def fix_member_type_field(tag: MemberTag, data: Dict):
        return {
            **data,
            "memberType": MemberType.FORMER if re.search(r'\d{2}.\d{2}.\d{4}',
                                                         data["details"][0]) else MemberType.ACTIVE
        }

    @staticmethod
    def add_birth_date_field(tag: MemberTag, data: Dict):
        return {
            **data,
            "birth_date": ""
        }

    @staticmethod
    def add_member_country_field(tag: MemberTag, data: Dict):
        return {
            **data,
            "country": "Polska"
        }

    @staticmethod
    def extract_member_image(current_image_data: MemberImageData, data: Dict):
        image = data.get("image", current_image_data.data or default_avatar)
        return base64.b64decode(image)

    @staticmethod
    def add_former_details_field(tag: MemberTag, data: Dict) -> Dict:
        former_details = {}

        if re.search(r'\d{2}.\d{2}.\d{4}', data["details"][0]):
            former_details = {
                "reason": data["details"][0]
            }

        return {
            **data,
            "former_details": json.dumps(former_details, ensure_ascii=False).encode('utf-8').decode()
        }
